 let modalNode=null,modalPlaceholder=null,modalReturnFocus=null;
  function openContent(id,title){const node=$(id);if(!node)return;openModalContent(node,title)}
  function normalizeEditorPane(pane){return ({behavior:'basics',advanced:'scope'})[pane]||pane||'basics'}
  function activateEditorSection(pane,title){const editor=$('aiAgentEditor'),section=normalizeEditorPane(pane);editor.dataset.aiActivePane=section;editor.querySelectorAll('[data-ai-section-nav]').forEach(button=>button.classList.toggle('is-active',button.dataset.aiSectionNav===section));if(title&&modalNode===editor)$('aiAgentsModalTitle').textContent=title;return section}
  function openEditorPane(pane,title){const editor=$('aiAgentEditor');activateEditorSection(pane,title);if(modalNode===editor)return;openModalContent(editor,title)}
  function showEditorSection(pane){const section=normalizeEditorPane(pane),titles={basics:'Основные настройки',scope:'Где работает агент',schedule:'График работы',stopping:'Когда агент должен остановиться',knowledge:'База знаний',triggers:'Триггеры и действия',dialogs:'Диалоги'};openEditorPane(section,titles[section]||'Настройки агента');if(section==='knowledge')loadKnowledge();if(section==='triggers')loadTriggers();if(section==='dialogs'){loadDrafts();loadHandoffs()}}
