  function renderEffectiveAutoSend(){const status=$('aiEffectiveAutoSend');if(!status)return;const reasons=[];if(!$('aiAgentEnabled').checked)reasons.push('агент выключен');if($('aiAgentMode').value!=='automatic')reasons.push('выбран Manual');if(!settings?.enabled)reasons.push('AI выключен для компании');if(settings?.operating_mode!=='active')reasons.push('компания работает в Test Mode');if(settings?.emergency_stop)reasons.push('включена аварийная остановка');if(!settings?.auto_send_enabled)reasons.push('автоотправка компании выключена');if(settings?.server_auto_send_enabled===false)reasons.push('автоотправка запрещена сервером');if(testMode?.emergency_stop)reasons.push('аварийная остановка Test Mode');if(reasons.length){status.textContent=`Автоматическая отправка сейчас недоступна: ${reasons.join('; ')}.`;status.dataset.state='warn'}else{status.textContent='Автоматическая отправка разрешена: перед каждой отправкой сервер повторно проверяет канал, диалог и вмешательство сотрудника.';status.dataset.state='good'}const modeHint=$('aiCompanyModeHint');if(modeHint)modeHint.textContent=settings?.operating_mode==='active'?'Сейчас Active Mode: агент работает только в сохранённой области.':'Сейчас Test Mode: агент работает только в подтверждённом тестовом диалоге.';const stopStatus=$('aiStoppingStatus');if(stopStatus){stopStatus.textContent='Автоматическое Resume отсутствует: после Human Mode или паузы сотрудник явно возобновляет AI для конкретного диалога.';stopStatus.dataset.state='good'}}
